// CHECK DUPLO, segunda metade: recalcula a chave do destino em JavaScript
// (implementacao independente da do banco) e compara com a que o banco
// mandou. Qualquer divergencia = nao envia.
function chave(p) {
  p = String(p || '');
  if (/@lid$/i.test(p)) { const d = p.replace(/\D/g, ''); return d ? 'lid:' + d : null; }
  let d = p.replace(/\D/g, '');
  if (!d) return null;
  if ((d.length === 10 || d.length === 11) && !d.startsWith('55')) d = '55' + d;
  if (/^55\d{10,11}$/.test(d)) return d.slice(0, 4) + d.slice(-8);
  return d;
}
return $input.all().map(it => {
  const j = it.json || {};
  let motivo = null;
  if (!j.id) motivo = 'sem_id';
  else if (!j.corpo || String(j.corpo.phone) !== String(j.telefone)) motivo = 'telefone_do_corpo_diferente';
  else if (!j.chave_esperada || chave(j.telefone) !== String(j.chave_esperada)) motivo = 'chave_nao_confere_js';
  else if (j.rota !== 'send-text' && j.rota !== 'send-image') motivo = 'rota_invalida';
  // A COLAGEM (12/09) mora no nosso site, nao no do catalogo: sem esta excecao
  // ela saia SEMPRE barrada aqui (foto_sem_codigo) -- visto no teste de 13/09.
  // So passa a colagem DAQUELE imovel: o arquivo tem o numero do codigo.
  else if (j.rota === 'send-image' && !(Number(j.codigo) > 0 && (/^https:\/\/imobeasy\.com\/system\/pictures\//.test(String(j.corpo.image || ''))
           // AS FOTOS DO SITE NOVO (01/10): imovel cadastrado por nos tem a foto em
           // imobeasy.online/fotos/<codigo>/ -- ou em fotos-captacao/<de onde
           // veio>/<codigo>/ (olx, whatsapp, crm). Eram 18 imoveis (5551, 9004...)
           // barrados aqui como foto_sem_codigo, queimando a trava de 24 h sem
           // mandar nada. Aqui o CODIGO no caminho e conferido: /fotos/5551/ so
           // vale para o 5551.
           || new RegExp('^https://imobeasy\\.online/fotos(-captacao/[a-z]+)?/' + Number(j.codigo) + '/').test(String(j.corpo.image || ''))
           || String(j.corpo.image || '') === 'https://imobeasy.online/colagens/' + Number(j.codigo) + '.jpg'))) motivo = 'foto_sem_codigo';
  else if (j.rota === 'send-text' && !String(j.corpo.message || '').trim()) motivo = 'texto_vazio';
  return { json: { ...j, enviar: motivo === null, motivo } };
});

// 01/10/2026: A NAY NAO LE MAIS IMAGEM (Pedro). Este no para aqui: nao
// baixa a foto e nao chama a OpenAI. NAO marque este no como desativado --
// no n8n o no desativado PASSA o dado adiante, e isso jogaria o item cru
// dentro do "Juntar mensagens". Ver scripts/madrugada/patch_sem_ler_imagem.py.
return [];
// LER IMAGEM E ARQUIVO (Tel, 16/09): "cria um fluxo que le imagem, audio e
// arquivo com a api do gpt". O audio ja era transcrito no ramo ao lado; a
// imagem nao tinha caminho nenhum, e o corretor ouvia "nao consigo abrir a
// imagem".
//
// A Z-API entrega a midia no proprio corpo do webhook -- `image.imageUrl`,
// `document.documentUrl`. Sem url, este ramo nao roda e o fluxo segue como era.
//
// O CORPO DO PEDIDO VAI MONTADO DAQUI (16/09). Escrito como expressao no
// proprio httpRequest, o no devolvia {"error":"invalid syntax"} em 31ms: o
// parser do n8n nao aceita `{{ JSON.stringify({...}) }}` comecando com chave.
// Montado aqui e mandado como string, a mesma chamada leu a foto do 5709.
const w = $('Webhook').first().json.body || {};

// SO LE O QUE CHEGA, NUNCA O QUE SAI (Tel, 16/09 -- corrigindo erro meu do
// mesmo dia). Este ramo lia o webhook direto, sem as exclusoes que o "Filtrar
// e normalizar" faz logo ali do lado. Resultado: cada foto que a PROPRIA NAY
// manda -- e ela manda quatro por card -- era enviada ao GPT para ser
// descrita. Alem do gasto, foi isso que quebrou o "Abrir turno" as 12:41: a
// resposta da OpenAI entrava na lista de mensagens do lote.
//
// As mesmas condicoes do "Filtrar e normalizar", pela mesma razao.
if (w.isGroup || w.isNewsletter || w.broadcast || w.isStatusReply) return [];
if (w.type !== 'ReceivedCallback') return [];
if (w.fromMe || w.fromApi) return [];

const img = w.image || {};
const doc = w.document || {};
const url = img.imageUrl || img.url || '';
const docUrl = doc.documentUrl || doc.url || '';
const mime = String(doc.mimeType || doc.mimetype || '');
// PDF e imagem o GPT le pela url. Planilha, .docx, video e audio nao passam
// por aqui: audio tem o ramo dele, e o resto vai para o Tel.
const docLegivel = docUrl && /pdf|image/i.test(mime);
const alvo = url || (docLegivel ? docUrl : '');
if (!alvo) return [];

const prompt = 'Voce trabalha numa imobiliaria de Manaus. Descreva em portugues, '
  + 'em ate 5 linhas, o que este arquivo mostra. Quando for imovel, diga o que da '
  + 'para ver: comodo, estado, mobilia. Quando for print de conversa, anuncio ou '
  + 'documento, transcreva o texto que aparece. Codigo de imovel, valor e endereco '
  + 'escreva exatamente como aparecem.';

const corpo = JSON.stringify({
  model: 'gpt-4o-mini',
  max_tokens: 400,
  messages: [{ role: 'user', content: [
    { type: 'text', text: prompt },
    { type: 'image_url', image_url: { url: alvo } }
  ]}]
});

return [{ json: {
  midia_url: alvo,
  tipo: url ? 'imagem' : 'arquivo',
  corpo: corpo,
  telefone: w.phone,
  nome: w.senderName
} }];

// O GPT LE O ARQUIVO, NAO A URL (22/09).
// Mandando a url da Z-API, quem precisa alcancar a foto e a OpenAI --
// e midia de WhatsApp expira e as vezes nem abre de fora. Baixando aqui
// (como o audio ja fazia) e mandando o arquivo, a leitura nao depende de
// ninguem alcancar nada.
//
// O BINARIO NAO ESTA EM `binary.data.data` (medido em 22/09). Este n8n
// guarda arquivo em DISCO: aquele campo vem com a etiqueta
// 'filesystem-v2', e foi exatamente isso que viajou para a OpenAI --
// 'data:image/png;base64,filesystem-v2' --, que respondeu 'you uploaded
// an unsupported image'. Quem traz os bytes e o helper abaixo.
const ent = $('Detectar imagem').first().json;
const OK = ['image/png', 'image/jpeg', 'image/gif', 'image/webp'];
let b64 = '', mime = 'image/jpeg';
try {
  const bin = $input.first().binary || {};
  const chave = bin.data ? 'data' : Object.keys(bin)[0];
  const d = bin[chave] || {};
  if (OK.indexOf(String(d.mimeType || '')) >= 0) { mime = d.mimeType; }
  const buf = await this.helpers.getBinaryDataBuffer(0, chave);
  b64 = buf.toString('base64');
} catch (e) { b64 = ''; }
const corpo = JSON.parse(ent.corpo);
// Sem o arquivo na mao, volta a valer a url: pior ler pela url do que
// nao ler.
if (b64) {
  corpo.messages[0].content[1].image_url.url = 'data:' + mime + ';base64,' + b64;
}
return [{ json: Object.assign({}, ent, { corpo: JSON.stringify(corpo),
                                        veio_arquivo: !!b64,
                                        bytes_lidos: b64.length }) }];

// O ESTADO E O QUE O JEV LE (77). Ele nao le imagem nem banco: le isto.
// A descricao que o GPT fez da foto e a transcricao do audio entram aqui.
//
// A MUDANCA: antes iam quatro campos (mensagem, quem fala, leitura da
// imagem, imovel em foco). Agora vai o estado inteiro -- inclusive a
// ULTIMA FALA DELA e os imoveis JA MOSTRADOS e RECUSADOS. Sem isso,
// "esse nao" e "pode ser" nao tem contra o que ser interpretados.
const base = $json;
const j = $('Juntar mensagens').first().json || {};
const cab = $('Abrir turno').first().json.cab || {};
const texto = String(j.texto || cab.texto || '').slice(0, 1500);

let est = {};
try { est = $('Ler estado').first().json.estado || {}; } catch (e) { est = {}; }

let leitura = '';
try {
  const im = $('Ler imagem (GPT)').all();
  if (im && im.length) {
    const c = ((im[0].json || {}).choices || [])[0];
    leitura = String(((c || {}).message || {}).content || '').trim();
  }
} catch (e) { leitura = ''; }

const estado = {
  mensagem: texto || '(sem texto)',
  quem_fala: est.papel || 'corretor',
  nome: est.nome || '',
  leitura_das_imagens: leitura || '',
  imovel_em_foco: est.codigo_foco ? String(est.codigo_foco) : '',
  imoveis_ja_mostrados: (est.codigos_mostrados || []).join(', '),
  imoveis_que_ele_recusou: (est.codigos_rejeitados || []).join(', '),
  ultima_coisa_que_a_nay_disse: String(est.ultima_fala_dela || '').slice(0, 500),
  tem_visita_pendente: est.visita_pendente ? 'sim' : 'nao',
  ultimas_trocas: (est.ultimas_trocas || []).map(function (t) {
    return 'ele: ' + String(t.ele || '').slice(0,160) + ' | ela: ' + String(t.ela || '').slice(0,160);
  }).join(' // '),
};

// OS CANDIDATOS. O Jev ESCOLHE entre opcoes -- ele nao extrai texto.
// Pedir "qual codigo ele quer" em texto livre devolveria numero
// inventado; oferecer 5727 / 5718 / nenhum devolve escolha com
// probabilidade. Teto de 8: lista longa piora a escolha.
const cands = [];
function poe(v) {
  const s = String(v || '').replace(/\D/g, '');
  if (s.length >= 3 && s.length <= 5 && cands.indexOf(s) < 0) cands.push(s);
}
poe(est.codigo_foco);
(j.codigosDele || []).forEach(poe);
(est.codigos_mostrados || []).forEach(poe);
const candidatos = cands.slice(0, 8);

function escolhasDeCodigo(comOutro) {
  const o = {};
  candidatos.forEach(function (c) { o[c] = 'E o imovel de codigo ' + c + '.'; });
  o.nenhum = 'Nenhum imovel especifico nesta mensagem.';
  if (comOutro) o.outro_nao_listado = 'Um imovel que nao esta nesta lista.';
  return o;
}

const perguntas = {
  intencao: {
    type: 'choice',
    instructions: 'O que ele quer NESTA mensagem? Leia junto com a ultima coisa que a Nay disse.',
    criteria: {"pedir_imovel":"Ele quer RECEBER imovel: pede card, fotos, opcoes, valores, ou descreve o que o cliente dele procura para a gente mandar.","rejeitar_imovel":"Ele esta RECUSANDO um imovel que ja mostramos: nao gostou, o cliente nao gostou, nao serve, quer outro no lugar.","pergunta_sobre_imovel":"Ele pergunta um DADO de um imovel que ja esta na conversa: valor, quartos, area, andar, condominio, disponibilidade, documentacao.","visita":"Ele quer marcar, remarcar, confirmar ou cancelar uma visita.","resultado_visita":"Ele esta contando COMO FOI uma visita que ja aconteceu, ou o que o cliente achou depois de ver.","cortesia":"So cumprimento, agradecimento ou confirmacao curta, sem assunto novo: oi, bom dia, ok, obrigado, blz.","oferta_de_imovel":"Ele esta OFERECENDO um imovel DELE para a imobiliaria, ou perguntando como anunciar com a gente.","assunto_geral":"Nao e sobre imovel do nosso catalogo: recado, duvida sobre a imobiliaria, parceria, comissao, grupo, reclamacao, assunto pessoal."}
  },
  codigo_quer: {
    type: 'choice',
    instructions: 'Qual imovel ele quer receber ou saber nesta mensagem?',
    criteria: escolhasDeCodigo(true),
  },
  codigo_rejeita: {
    type: 'choice',
    instructions: 'Qual imovel ele esta RECUSANDO nesta mensagem? So quando ele diz que nao serve ou nao gostou.',
    criteria: escolhasDeCodigo(false),
  },
  oferta: {
    type: 'noul',
    instructions: 'A pessoa esta oferecendo um imovel DELA para a imobiliaria?',
    criteria: { true: 'Diz que tem um imovel e quer enviar, cadastrar ou anunciar com a gente.', false: 'Esta perguntando sobre imovel nosso, ou falando de outra coisa.' },
  },
  cortesia: {
    type: 'noul',
    instructions: 'A mensagem e apenas cortesia, sem assunto novo?',
    criteria: { true: 'So agradecimento, confirmacao ou saudacao: ok, obrigado, bom dia, blz.', false: 'Tem pergunta, pedido ou informacao nova.' },
  },
  o_que_mandou: {
    type: 'choice',
    instructions: 'O que a pessoa mandou nas imagens ou arquivos?',
    criteria: { anuncio_dele: 'Fotos ou print de um imovel DELE, que ele quer oferecer.', documento: 'Documento, contrato, comprovante, ficha, print de conversa.', duvida_sobre_nosso: 'Foto de um imovel NOSSO, perguntando algo sobre ele.', nao_da_para_saber: 'Nao veio imagem, ou nao da para dizer pelo que veio.' },
  },
};

const corpo = JSON.stringify({
  model: 'typesafe/jev-1.13',
  state: estado,
  questions: perguntas,
});
return [{ json: Object.assign({}, base, { corpo, texto_lido: texto, candidatos: candidatos }) }];

// O JEV DEVOLVE NUMERO, nao prosa: uma probabilidade por pergunta.
// Aqui so se empacota; quem compara com os pisos e o banco, em
// `nai_decidir_com_jev` -- para o Tel poder mexer sem deploy.
//
// SE O JEV CAIR (o no tem onError), nao para nada: vale a reserva
// pelo proprio texto, e a conferencia do banco corrige por cima.
const j = $json || {};
const a = j.answers || {};
const tem = Object.keys(a).length > 0;

if (!tem) {
  const t = String(($('Montar pergunta ao Jev').first().json || {}).texto_lido || '')
    .toLowerCase();
  const deImovel = /(imovel|imóvel|apartamento|casa|aluguel|loca|venda|visita|foto|dispon|c[oó]digo|condom)/.test(t);
  return [{ json: { jev: {}, reserva: true,
                    atendente: deImovel ? 'imoveis' : 'secretaria' } }];
}

return [{ json: { jev: Object.assign({}, a, {
  modelo: j.model || null,
  custo: (j.usage && j.usage.cost) || null,
}), reserva: false } }];

// Devolve o MESMO item que o roteador montou, so trocando a rota: os nos
// de baixo leem campos dele.
const base = $('Rotear pelo cabeçalho').first().json;
const d = $('Decidir quem responde').first().json || {};
const at = d.atendente === 'secretaria' ? 'secretaria' : 'agente';
return [{ json: Object.assign({}, base, { rota: at, atendente: d.atendente }) }];

